271	    private int countNamesakes(Owner owner) {
272	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
273	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
274	        return (int) ownerRepository.findAll().stream()
275	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
276	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
277	            .count();
278	    }
