280	    /**
281	     * Reconcile the owner's household. Owners are in the same household when their last name and
282	     * address match (compared case-insensitively with collapsed whitespace). When another owner
283	     * already lives there, the create is rejected with {@link DuplicateHouseholdException} unless
284	     * {@code sharesHousehold} is set, in which case the new owner and every existing member are
285	     * given the same stable shared {@code householdId}.
286	     */
287	    private void assignHousehold(Owner owner, boolean sharesHousehold) {
288	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
289	        String address = AddressNormalizer.canonical(owner.getAddress());
290	        List<Owner> householdMembers = ownerRepository.findAll().stream()
291	            .filter(existing -> lastName.equals(IdentityNormalizer.normalize(existing.getLastName()))
292	                && address.equals(AddressNormalizer.canonical(existing.getAddress())))
293	            .toList();
294	        if (householdMembers.isEmpty()) {
295	            return;
296	        }
297	        if (!sharesHousehold) {
298	            throw new DuplicateHouseholdException(
299	                "an owner with last name " + owner.getLastName() + " already lives at " + owner.getAddress());
300	        }
301	        String householdId = householdMembers.stream()
302	            .map(Owner::getHouseholdId)
303	            .filter(Objects::nonNull)
304	            .findFirst()
305	            .orElseGet(() -> deriveHouseholdId(lastName, address));
306	        owner.setHouseholdId(householdId);
