327	    /**
328	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
329	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
330	     * is persisted, so it reflects the owners present at creation time.
331	     */
332	    private void rejectWhenCityAtCapacity(Owner owner) {
333	        String city = IdentityNormalizer.normalize(owner.getCity());
334	        long cityOwners = ownerRepository.findAll().stream()
335	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
336	            .count();
337	        if (cityOwners >= CITY_CAPACITY) {
338	            throw new CityCapacityExceededException(
339	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
340	        }
341	    }
