343	    /**
344	     * Builds the customer code {@code '<CITY3>-<LAST3>-<NNNN>'}: the upper-cased first
345	     * three letters of the owner's {@code city}, a hyphen, the upper-cased first three
346	     * letters of {@code lastName}, a hyphen, and a 4-digit zero-padded per-city sequence
347	     * equal to one more than the number of owners already in that city (compared
348	     * case-insensitively with collapsed whitespace).
349	     */
350	    private String nextCustomerCode(Owner owner) {
351	        String city3 = prefix3(owner.getCity());
352	        String last3 = prefix3(owner.getLastName());
353	        String city = IdentityNormalizer.normalize(owner.getCity());
354	        long sequence = ownerRepository.findAll().stream()
355	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
356	            .count() + 1L;
357	        return String.format("%s-%s-%04d", city3, last3, sequence);
358	    }
