360	    /**
361	     * Returns the upper-cased first three letters of {@code value}, or fewer when the value
362	     * is shorter; a {@code null} value yields an empty string.
363	     */
364	    private static String prefix3(String value) {
365	        String name = value == null ? "" : value;
366	        return name.substring(0, Math.min(3, name.length())).toUpperCase();
367	    }
