388	        try {
389	            return supplier.get();
390	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
391	            // Just ignore not found exceptions for Jdbc/Jpa realization
392	            return null;
393	        }
394	    }
